const RFC9110 = 'RFC 9110 HTTP Semantics. https://www.rfc-editor.org/rfc/rfc9110';
const SEMVER = 'Semantic Versioning. https://semver.org/';
const OTELE = 'OpenTelemetry Documentation. https://opentelemetry.io/docs/';
const CLRS = 'Cormen et al. Introduction to Algorithms (CLRS). https://mitpress.mit.edu/9780262046305/introduction-to-algorithms/';

