    goal: '能把一个 div 堆砌的页面系统化重构为语义结构，并用回归清单确认功能与可访问性不退步。',
    guidedPractice: '选一个纯 div 页面，逐步替换区域标签、补全标题层级与列表语义，每步验证外观未变。',
    independentPractice: '为重构写一份回归清单，覆盖视觉、键盘操作、读屏顺序和表单功能，逐项打勾。',
