// ── H4 可访问性、SEO 与国际化 ─────────────────────────────────────
const h4Stage = '可访问性、SEO 与国际化';
const h4Name = (topic: string) => `编程通识 · ${h4Stage}：${topic}`;

const HANDWRITTEN_PROGRAMMING_FOUNDATION_H4_COURSES_BASE: readonly ProgrammingCourseSeed[] = [
  {
    name: h4Name('键盘路径、焦点顺序与跳转链接'),
    track,
    minutes: 38,
    prerequisite: '能区分链接、按钮等可交互元素，并理解 DOM 树与页面渲染顺序的关系。',
    goal: '能用键盘独立走完一个页面的全部交互，能判断焦点顺序是否与视觉顺序一致，并会写跳转链接与 :focus-visible 样式。',
    guidedPractice: '关闭鼠标只用 Tab 键走完导航到表单提交的完整路径，记录每个焦点落点，为跳过导航写一条 skip link，并用 :focus-visible 恢复焦点环。',
    independentPractice: '挑一个真实页面做键盘审计：列出焦点顺序错乱的位置、被删掉的焦点环、不可见却可聚焦的元素，逐项修复后重走一遍键盘路径验证。',
    commonErrors: ['用 outline: none 删除焦点环却没有提供任何替代的聚焦指示，键盘用户找不到当前位置。', '用正 tabindex 手动编排 Tab 顺序，后续插入元素后整条链乱掉，维护成本远高于收益。'],
    sourceRefs: [
      'MDN Web Docs. https://developer.mozilla.org/',
      'WAI-ARIA Authoring Practices. https://www.w3.org/WAI/ARIA/apg/',
    ],
    steps: [
      ['Tab 顺序即 DOM 顺序', '浏览器把可聚焦元素按文档流排成一条 Tab 链，Tab 前进、Shift+Tab 后退，链的默认走向就是 DOM 的书写顺序。CSS 的 order、flex 布局或绝对定位可以改变视觉位置，却改变不了这条链。想让键盘路径合理，正确做法是调整 HTML 结构本身，而不是在样式里搬位置。', '顺序归 DOM 决定'],
      ['tabindex 的三个取值', '不写或写 0 表示元素按 DOM 顺序进入 Tab 链；-1 表示可以从脚本 focus() 聚焦但不进 Tab 链，常用于把弹窗关闭后的焦点送回触发按钮；正数会强行重排整条链、与 DOM 顺序打架，是公认的坏味道。日常写 0 与 -1 就够，正数基本不需要。', '正数基本不要碰'],
      ['跳转链接直达主内容', '跳转链接（skip link）是页面第一个可聚焦元素，默认藏在屏幕外，获得焦点时滑入视野，激活后把焦点与滚动位置一并送到主内容区。键盘用户在多层导航页面里按一次 Enter 就能跳过几十个导航链接，这是成本最低、收益最直接的一项无障碍改造。', '一跳直达主内容'],
      ['焦点可见性不能被抹掉', '浏览器会给聚焦元素画一圈焦点环，很多设计嫌它难看就用 outline: none 一刀切掉，键盘用户随即彻底失去位置线索。正确的替代方案是用 :focus-visible 区分来源：鼠标点击不画环、键盘聚焦画环，或把环改成符合品牌的高对比样式，总之不能取消。', '焦点环只换不删'],
      ['视觉布局骗不过焦点顺序', '常见陷阱是视觉顺序与 DOM 顺序不一致：flex 的 row-reverse 或绝对定位让按钮看起来在左、Tab 却先到右边；折叠面板里用 opacity: 0 遮住的链接仍可聚焦，Tab 会走到看不见的东西上。验收方法是只用键盘从头走一遍，核对每个焦点落点与视觉预期是否一致。', '键盘走查见真章'],
    ],
  },
{
    name: h4Name('ARIA 的角色、名称和状态'),
    track,
    minutes: 37,
    prerequisite: '理解原生 HTML 控件的语义，知道读屏软件如何朗读页面元素。',
    goal: '能按角色、名称、状态三要素为自定义组件补齐 ARIA 语义，判断何时应改用原生元素，并用开发者工具的无障碍树验证播报结果。',
    guidedPractice: '把一个 div 手写的折叠按钮换成原生 button 加 aria-expanded，用开发者工具的无障碍树核对角色、名称、状态三项是否齐备，再给图标按钮补上 aria-label。',
    independentPractice: '审查一个含图标按钮、自绘开关与异步提示的页面：逐个核对名称是否缺失、状态是否播报、live region 是否预先挂载，修完并记录前后差异。',
    commonErrors: ['给已有可见文字的元素再叠一个 aria-label，读屏播报与屏幕显示不一致，听的人无从对上。', '用 div 加 role="button" 却没补键盘事件，鼠标能点、Tab 能到、按 Enter 没反应。'],
    sourceRefs: [
      'WAI-ARIA Authoring Practices. https://www.w3.org/WAI/ARIA/apg/',
      'MDN Web Docs. https://developer.mozilla.org/',
    ],
    steps: [
      ['角色名称状态三要素', '读屏软件向用户播报三件事：这是什么（角色）、叫什么（名称）、现在怎样（状态）。一个折叠按钮需要 button 角色、可见文字作名称、aria-expanded 表达展开状态，三者齐了听的人才能正确决策。写 ARIA 时按这三个问题逐个自查，缺一个就补一个。', '缺哪个补哪个'],
      ['第一条规则是别用 ARIA', 'ARIA 作者实践指南的第一条规则是：有原生元素就不要用 ARIA。原生 button 自带角色、键盘行为与状态播报；一个 div 加 role="button" 还得手写 Enter 与空格的 keydown 处理，漏一处键盘用户就进不去。能用 select 就不用 div 拼下拉，能用 details 就不用手写折叠。', '原生优先于 ARIA'],
      ['标签与可见文本的关系', 'aria-label 或 aria-labelledby 会覆盖元素的可见文字成为读屏名称。图标按钮没有可见文字，必须用 aria-label 补名称；但已有可见文本的元素再写 aria-label，读到的内容与看到的文字对不上，反而造成困惑。原则是名称优先来自可见文本，补写只发生在文本缺失时。', '名称来自可见文本'],
      ['用状态属性播报变化', 'aria-expanded 告诉读屏折叠区是开是关，aria-checked 表达自绘开关的选中态，aria-disabled 表达不可用。这些属性改的是语义状态而不是外观，改值时读屏会自动播报，前提是挂在对的元素上。手写开关组件时，外观切换与状态属性必须同步更新，漏一个读屏用户就收不到变化。', '状态与外观同步'],
      ['live region 播报', '表单提交后的成功提示、购物车数量变化这类异步更新发生时，读屏用户的焦点往往不在那里，默认听不到。aria-live="polite" 声明的区域内容变化时会被主动播报，assertive 用于必须打断的告警。要点是区域要预先挂在 DOM 里、更新时只改内容，动态插入整个区域的播报时机不可靠。', '区域先挂后更新'],
    ],
  },
{
    name: h4Name('对比度、缩放与动效偏好'),
    track,
    minutes: 36,
    prerequisite: '了解 CSS 颜色与媒体查询的基本用法，能读懂开发者工具的计算样式。',
    goal: '能用工具把页面文字对比度修到 WCAG AA 标准以上，保证 200% 缩放后功能完整，并实现 prefers-reduced-motion 的降级动画。',
    guidedPractice: '跑一遍 axe 拿到对比度违规清单，在设计令牌里替换不达标颜色，同时写 reduced-motion 媒体查询把动画降级，最后把浏览器缩放到 200% 复查功能。',
    independentPractice: '对一个营销页做无障碍体检：灰度测试确认颜色不是唯一信息载体、放大两倍走一遍主流程、补齐动效降级，输出前后问题清单与修复记录。',
    commonErrors: ['用浅灰文字营造高级感，实测对比度只有 3:1 出头，正文可读性达不到 AA 标准。', 'reduced-motion 命中时把加载指示动画也一并关掉，用户分不清页面是在加载还是卡死。'],
    sourceRefs: [
      'WCAG. https://www.w3.org/WAI/WCAG22/quickref/',
      'web.dev. https://web.dev/',
    ],
    steps: [
      ['WCAG 的两条对比线', 'WCAG AA 要求正文文字与背景的对比度至少 4.5:1，18pt 以上大字与粗体降到 3:1，图形与控件边框同样按 3:1 考核。数字来自亮度比值的公式计算，肉眼觉得还行经常不达标，用对比度检查工具量出来的数值才是依据。品牌浅灰配白底是最常见的失分点。', '以量出的数值为准'],
      ['颜色不是唯一载体', '色盲用户分不清红绿，错误状态若只靠红色区分，信息就丢了。表单校验要同时给图标、文字说明或边框样式，图表系列要加形状与纹理区分。设计时做一个灰度测试：把页面去色后信息仍能读全，说明颜色只是冗余通道而不是唯一通道。', '颜色之外留双通道'],
      ['200% 缩放不丢功能', 'AA 要求页面放大到 200% 后内容与功能不丢失。用相对单位与响应式布局的页面缩放后自然重排；用固定像素、超小容器或 hover 才能展开菜单的页面，放大后文字被裁切、功能够不着。检查方法是浏览器放大两倍走一遍主流程，看有没有内容溢出或交互失效。', '放大两倍走一遍'],
      ['动效偏好可以被尊重', 'prefers-reduced-motion 查询读到系统里减少动态效果的开关，用户用它规避晕动症或前庭障碍。媒体查询命中时把大位移动画换成淡入淡出、停掉视差滚动与自动轮播。装饰动画关掉不影响功能，但加载指示这类功能性动画要保留，只是换成低动方式。', '装饰降级功能保留'],
      ['用工具量化再动手修', '逐个肉眼判断颜色太不可靠，流程应是先跑 axe 或 Lighthouse 拿到全部对比度违规清单，再到设计令牌层面修正：改的是主题变量而不是逐处内联色值，一次修正全局生效。改完重扫确认清零，并把达标组合沉淀成调色板约束，防止下一轮设计又踩回去。', '修令牌一次清零'],
    ],
  },
{
    name: h4Name('SEO、canonical 与 robots'),
    track,
    minutes: 39,
    prerequisite: '了解搜索引擎抓取与索引的基本流程，能在页面 head 里插入 link 与 meta 标签。',
    goal: '能为一组重复 URL 写对 canonical，区分并正确配置 robots.txt 与 meta robots，管理 nofollow 链接并维护一份与实际页面一致的 sitemap。',
    guidedPractice: '给带排序与筛选参数的列表页选一个规范地址写 canonical，在根目录配置 robots.txt，对一个测试页面加 noindex，用搜索平台工具验证抓取与索引效果。',
    independentPractice: '为一个小站做 SEO 体检：核对每页标题唯一性、检查重复 URL 是否收敛、robots 指令是否自洽、sitemap 是否与实际地址一致，输出整改清单并逐项落实。',
    commonErrors: ['robots.txt 里 Disallow 了某目录，又期望它不出现在搜索结果，实际它仍可能凭外链被展示。', '同一内容的多套 URL 各自为政，没写 canonical，权重被重复页面摊薄，搜索结果里出现多个近似条目。'],
    sourceRefs: [
      'Google Search Central. https://developers.google.com/search',
      'web.dev. https://web.dev/',
    ],
    steps: [
      ['canonical 收敛重复', '同一内容经带参数的 URL、排序变体或打印版可以生成无数地址，搜索引擎会当作重复页面分散权重。link rel="canonical" 声明哪个地址是规范版本，重复的信号集中到它名下。声明必须自洽：规范页面要返回 200、不能互相指认形成环，跨域转载也可以用它指向原文。', '信号收敛到规范页'],
      ['robots.txt 管抓取', 'robots.txt 是站点根目录的纯文本协议，声明哪些路径允许爬虫抓取，控制的是抓不抓。它管不了收录展示：被禁止抓取的地址仍可能凭外链出现在结果里。文件写错一行 Disallow: / 就能让全站从索引消失，改动后先用搜索平台的 robots 测试器验证再发布。', '禁抓不等于不收录'],
      ['meta robots 分工', '与 robots.txt 不同，meta robots 写在单个 HTML 文档的 head 里，noindex 表示该页面不要进入索引，nofollow 表示不要顺着它的链接传递权重。它控制收不收，但前提是页面能被抓到——若同时被 robots.txt 禁止抓取，爬虫根本读不到这条 meta，指令等于失效。', '要能被抓到才生效'],
      ['nofollow 切断权重流', '链接默认向目标传递权重，付费链接、用户可随意编辑的评论区链接应当加 rel="nofollow"（或语义更明确的 sponsored、ugc），避免站点为低质量目标背书。nofollow 不是安全机制，垃圾评论该删还是要删；它只是告诉搜索引擎这条链接不构成推荐。', '不作推荐的声明'],
      ['标题唯一与 sitemap', '每个页面的 title 应独一无二并写清内容主题，重复标题会让搜索引擎难以区分该收录哪个版本。sitemap.xml 把希望收录的地址主动报给搜索引擎，配合搜索平台提交加快发现，但它只是清单不是强制令，列进去不保证收录，质量差的页面照样被排除。', '清单不保证收录'],
    ],
  },
{
    name: h4Name('语言、方向与本地化结构'),
    track,
    minutes: 36,
    prerequisite: '理解 HTML 文档结构并使用过 CSS 布局属性，了解多语言站点的基本组织方式。',
    goal: '能正确声明页面语言与文字方向，用 hreflang 打通多语言版本互认，并让布局经得起文本长度变化与本地化日期数字格式的检验。',
    guidedPractice: '给一个页面加 lang 与 dir="rtl" 观察整体翻转，把写死的 left/right 改成逻辑属性，再用 Intl 对象替换手写拼接的日期与数字格式。',
    independentPractice: '把一个单语页面扩成双语结构：补 lang、hreflang 互指、RTL 检查与伪本地化拉长测试，记录每个暴露的布局问题与对应修复方式。',
    commonErrors: ['html 忘写 lang 或标错语言，读屏软件用错发音引擎，中文被英文语音读得无法辨认。', '样式写死 left、right 与固定像素宽度，切到 RTL 语言或德语长文本后布局错位、文字溢出。'],
    sourceRefs: [
      'MDN Web Docs. https://developer.mozilla.org/',
      'HTML Living Standard. https://html.spec.whatwg.org/',
    ],
    steps: [
      ['html lang 声明语言', 'html 元素的 lang 属性向读屏软件声明页面语言，读屏据此选择发音引擎：中文页面标成英文会用英文音库读中文，几乎听不懂。lang 还影响浏览器的翻译提示、连字符断行与引号样式。多语言混排时在局部元素上再标 lang，让这段文字按它自己的语言处理。', 'lang 决定读法'],
      ['dir=rtl 镜像整条轴', '阿拉伯语、希伯来语从右向左书写，html 上设 dir="rtl" 后文本流、列表编号、表格列序整体翻转。布局要用 margin-inline、padding-inline 这类逻辑属性书写，写死 left/right 的样式在 RTL 下必然错位；图标里的方向符号如箭头需要单独判断是否该翻转。', '用逻辑属性写布局'],
      ['hreflang 标注语言版', '多语言站点为同一内容准备多个语言版本的 URL，每个版本用 link rel="alternate" hreflang 声明自己和其他版本的语言与地区，各版本互相指认形成闭环，搜索引擎据此把日语用户引向日文页面。缺一条互指或地址写错，闭环断裂，搜索引擎就可能把用户引到错误的语言版本。', '互指成环才算数'],
      ['文本长度撑破固定布局', '同一句话译成德语长约三成、译成中文又可能缩短一半，按钮里写死的宽度会让德语文字溢出、俄语换行错乱。布局要按容器随内容伸缩来设计：用 min-width 与弹性间距代替固定宽度，给超长文本留省略号方案。测试时用伪本地化把字符串拉长加标记，提前暴露这类问题。', '容器随内容伸缩'],
      ['日期数字也有本地格式', '3/4/2026 在美国是三月四日、在欧洲是四月三日；小数点在欧洲可能是逗号；千位分隔符各文化不同。Intl.DateTimeFormat 与 Intl.NumberFormat 按传入的 locale 输出正确格式，避免手写拼接。排序同理要用 locale 感知的 Collator，别用默认字节序去排中文拼音。', '格式交给 Intl'],
    ],
  },
{
    name: h4Name('无障碍与 SEO 联合验收'),
    track,
    minutes: 40,
    prerequisite: '完成本阶段前五门课的学习，能独立完成键盘走查与扫描工具的基本操作。',
    goal: '能组织一次发布前的无障碍与 SEO 联合验收：键盘走查主流程、解读扫描报告并区分机器与人工的责任边界、逐项执行检查清单并留下记录。',
    guidedPractice: '对一个页面同时跑 Lighthouse 与键盘走查，把扫描发现与人工发现分成两列对比，体会哪些问题只有人工能发现，并整理成一份可复用的验收清单。',
    independentPractice: '为一个小站设计发布门禁：CI 接入 axe 阈值、编写 SEO 检查清单、排期键盘走查，并对一个真实版本完整执行一轮，记录每项拦截结果。',
    commonErrors: ['把 Lighthouse 分数当作唯一验收标准，扫描通过但键盘根本走不进菜单的页面照样上线。', '验收只做一次不做回归，后续迭代加回来的新组件重新引入缺 alt 与对比度不达标的老问题。'],
    sourceRefs: [
      'web.dev. https://web.dev/',
      'WCAG. https://www.w3.org/WAI/WCAG22/quickref/',
    ],
    steps: [
      ['键盘先于工具走一遍', '扫描器只能发现可枚举的问题，焦点顺序是否合理、跳转链接是否顺手、折叠面板键盘能否操作，只有人用键盘走一遍主流程才知道。验收从拔掉鼠标开始：注册、搜索、下单走完整链路，记录每个卡点。人工先行做完，扫描结果才有解释的基准。', '人工先行定基准'],
      ['扫描与人工各管一段', 'Lighthouse 与 axe 能自动化检出对比度不足、缺 alt、ARIA 用错这类确定性问题，覆盖率大约一半：语义是否恰当、播报是否可懂、路径是否顺手，机器判断不了。正确关系是扫描兜底确定性缺陷、人工复核体验问题，扫描零违规是底线，不是达标线。', '扫描是底线不是达标线'],
      ['两套检查共享同一批根因', '无障碍与 SEO 的缺陷常同源：标题层级混乱既让读屏用户摸不到结构，也让搜索引擎抓不准主题；alt 缺失既伤读屏又丢图片搜索入口；lang 缺失影响读屏发音也影响地区收录。修复时一次改动同时进两份清单，验收表不必拆成两张重复的表。', '一次修复两份清单'],
      ['SEO 检查清单落地', '发布前逐项核对：每个页面标题唯一且反映内容、canonical 自洽、robots 指令不会误伤、sitemap 与实际地址一致、结构化数据通过校验。清单的意义在执行方式——每一项都要有通过或不通过的实际检查动作，而不是一句已关注。勾选依据记录在案，出问题能回溯。', '每项检查留痕'],
      ['把验收做成发布门禁', '验收做完一次就忘是常态，可持续的做法是把它放进发布流程：axe 扫描接进 CI，关键页面报错即阻断合并；Lighthouse 分数设阈值定期回归；人工键盘走查固定在版本上线前执行。门禁的价值不在拦人，而在让缺陷停留在成本最低的阶段——本地修复，而不是上线后返工。', '缺陷拦在上线前'],
    ],
  },
];

// ── H5 页面性能与企业站点交付 ─────────────────────────────────────
const h5Stage = '页面性能与企业站点交付';
const h5Name = (topic: string) => `编程通识 · ${h5Stage}：${topic}`;

