    guidedPractice: '给一个接入了统计与客服脚本的页面配置 CSP：先以 Report-Only 模式收集违规报告，整理来源白名单后切换为强制模式，同时给固定版本的第三方库加上 integrity 哈希，验证篡改场景下浏览器确实拒绝执行。',
