    guidedPractice: '对一个真实页面跑 Lighthouse 并接入简化 RUM 采集：定位 LCP 元素与最大 CLS 来源，修完宽高缺失与长任务后复测，把三个指标的实验室得分与真实用户分布放在一起对比并解释差异。',
    independentPractice: '为自己的站点设立性能预算：LCP、CLS、INP 各定阈值，脚本与图片总量定上限，接入 CI 检查使超预算的提交无法合入，并在一次真实发布中验证回归防线确实生效。',
    commonErrors: ['只看实验室满分就认为性能达标，忽略真实用户在低端设备上的指标分布。', '把指标阈值记混，用 CLS 的 0.1 去要求 LCP 或用毫秒去衡量布局偏移。'],
