  '基准要控制变量': '，固定随机种子、输入规模、运行时版本与运行命令后再比较。',
  '连接池复用已建立的连接': '，比较首次连接与复用连接的握手耗时并核对池内空闲数。',
  '重试预算防止故障放大': '，把退避、抖动和最大次数相加，预算不得超过上游超时。',
  '用最坏耗时反推参数是否合理': '，逐项累加连接、读取、退避与重试，再与上游截止时间比较。',
  '用竞争指标与队列长度验证': '，同时记录锁等待、活跃线程数、队列长度和请求延迟。',
